57	                    print!(" ");
58	                    print!("{}", BS as char);
59	                    line.pop();
60	                }
61	            }
62	            _ => {
63	                print!("{}", c as char);
64	                line.push(c as char);
65	            }
66	        }
67	    }
68	}
