21	/// 这个接口定义了向控制台“输出”这件事。
22	pub trait Console: Sync {
23	    /// 向控制台放置一个字符。
24	    fn put_char(&self, c: u8);
25	
26	    /// 向控制台放置一个字符串。
27	    ///
28	    /// 如果使用了锁，覆盖这个实现以免反复获取和释放锁。
29	    #[inline]
30	    fn put_str(&self, s: &str) {
31	        for c in s.bytes() {
32	            self.put_char(c);
33	        }
34	    }
35	}
