138	/// 打印。
139	///
140	/// 给宏用的，用户不会直接调它。
141	/// 使用栈上缓冲区收集格式化输出，然后一次性输出到控制台。
142	#[doc(hidden)]
143	#[inline]
144	pub fn _print(args: fmt::Arguments) {
145	    // 注意：这里故意不直接调用底层 put_char，而是经由 PrintBuffer 聚合输出。
146	    let mut buffer = PrintBuffer::new();
147	    buffer.write_fmt(args).unwrap();
