159	/// 格式化打印并换行。
160	#[macro_export]
161	macro_rules! println {
162	    () => ($crate::print!("\n"));
163	    ($($arg:tt)*) => {{
164	        $crate::_print(core::format_args!($($arg)*));
165	        $crate::println!();
166	    }}
