181	/// 实现 `log::Log` trait，提供分级日志。
182	impl log::Log for Logger {
183	    #[inline]
184	    fn enabled(&self, _metadata: &log::Metadata) -> bool {
185	        true
186	    }
187	
188	    #[inline]
189	    fn log(&self, record: &log::Record) {
190	        use log::Level::*;
191	        // ANSI 颜色仅用于教学调试体验，不影响日志语义。
192	        let color_code: u8 = match record.level() {
193	            Error => 31,
194	            Warn => 93,
195	            Info => 34,
196	            Debug => 32,
197	            Trace => 90,
198	        };
199	        println!(
200	            "\x1b[{color_code}m[{:>5}] {}\x1b[0m",
201	            record.level(),
202	            record.args(),
203	        );
204	    }
205	
206	    fn flush(&self) {}
207	}
